/bin/zsh -lc "node - <<'NODE'
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
let source = html.match(/<script>([\\s\\S]*?)<\\/script>/i)[1];
source = source.replace(
  'window.addEventListener(\"resize\", resize);',
  'globalThis.__simulation = { ball, walls, get angle() { return angle; }, get centerX() { return centerX; }, get centerY() { return centerY; }, radius: BALL_RADIUS };\\n      window.addEventListener(\"resize\", resize);'
);
let nextFrame = null;
const noop = () => {};
const drawingContext = {
  setTransform: noop, clearRect: noop, beginPath: noop, moveTo: noop,
  lineTo: noop, closePath: noop, stroke: noop, arc: noop, fill: noop
};
const canvas = { width: 0, height: 0, getContext: () => drawingContext };
const sandbox = {
  document: { getElementById: () => canvas },
  window: { innerWidth: 1000, innerHeight: 800, devicePixelRatio: 1, addEventListener: noop },
  performance: { now: () => 0 },
  requestAnimationFrame: (callback) => { nextFrame = callback; },
  console,
  Math
};
vm.createContext(sandbox);
vm.runInContext(source, sandbox);
const simulation = sandbox.__simulation;
if ("'!simulation || !nextFrame) throw new Error('"'Simulation did not initialize');

function penetration() {
  const cosine = Math.cos(simulation.angle);
  const sine = Math.sin(simulation.angle);
  const dx = simulation.ball.x - simulation.centerX;
  const dy = simulation.ball.y - simulation.centerY;
  const localX = cosine * dx + sine * dy;
  const localY = -sine * dx + cosine * dy;
  let maximum = -Infinity;
  for (const wall of simulation.walls) {
    const signed = (localX - wall.start.x) * wall.normalX +
      (localY - wall.start.y) * wall.normalY;
    maximum = Math.max(maximum, signed + simulation.radius);
  }
  return maximum;
}

let time = 0;
for (let frame = 0; frame < 36000; frame += 1) {
  time += 1000 / 60;
  const callback = nextFrame;
  nextFrame = null;
  callback(time);
  if ("'!nextFrame) throw new Error(`Animation stopped at frame ${frame}`);
  const overlap = penetration();
  if (!Number.isFinite(overlap) || overlap > 1e-7) {
    throw new Error(`Containment failed at frame ${frame}: ${overlap}`);
  }
}

simulation.ball.x = simulation.centerX;
simulation.ball.y = simulation.centerY;
simulation.ball.velocityX = 1000000;
simulation.ball.velocityY = -750000;
time += 1000 / 60;
nextFrame(time);
const stressOverlap = penetration();
if (!Number.isFinite(stressOverlap) || stressOverlap > 1e-7) {
  throw new Error(`Extreme-speed containment failed: ${stressOverlap}`);
}

console.log('"'PASS: 36,000 frames (10 simulated minutes) remained contained.');
console.log("'`PASS: extreme-speed tunneling stress remained contained (max penetration ${stressOverlap.toExponential(2)}px).`);
NODE'

